# Description: EnhancedHybridOptimizer with dynamic population sizing and learning-guided local exploitation for improved convergence in heterogeneous search spaces.
# Code: 
```python
import numpy as np

class EnhancedHybridOptimizer:
    def __init__(self, budget, dim):
        self.budget = budget
        self.dim = dim

    def __call__(self, func):
        lb, ub = np.array(func.bounds.lb), np.array(func.bounds.ub)
        initial_population_size = 10 * self.dim
        population_size = initial_population_size
        population = np.random.uniform(lb, ub, (population_size, self.dim))
        fitness = np.array([func(ind) for ind in population])
        evaluations = len(fitness)

        def adaptive_step_size(base_step, iteration):
            return base_step * (0.5 ** (iteration / (self.budget // initial_population_size)))

        def neighborhood_search(ind, step_size=0.1):
            candidate = ind + np.random.normal(0, step_size, size=self.dim)
            return np.clip(candidate, lb, ub)

        def learning_guided_local_search(ind, step_size=0.1, steps=5):
            best_candidate = ind.copy()
            best_fitness = func(ind)
            for _ in range(steps):
                candidate = neighborhood_search(ind, step_size)
                candidate_fitness = func(candidate)
                if candidate_fitness < best_fitness:
                    best_candidate, best_fitness = candidate, candidate_fitness
            return best_candidate

        def adaptive_differential_evolution():
            nonlocal evaluations, population_size
            for iteration in range(self.budget // initial_population_size):
                success_count = 0
                diversity = np.std(population, axis=0).mean()
                diversity_factor = 1 / (1 + np.exp(-10 * (diversity - 0.5)))
                adjusted_mut_factor = 0.8 + (0.5 * diversity_factor)
                for i in range(population_size):
                    if evaluations >= self.budget:
                        return
                    idxs = np.random.choice(np.delete(np.arange(population_size), i), 3, replace=False)
                    x0, x1, x2 = population[idxs]
                    mut_factor = adaptive_step_size(adjusted_mut_factor, iteration)
                    mutant = np.clip(x0 + mut_factor * (x1 - x2), lb, ub)
                    cross_prob = 0.9 * (1 - success_count / (i + 1))
                    cross_points = np.random.rand(self.dim) < cross_prob
                    trial = np.where(cross_points, mutant, population[i])
                    trial_fitness = func(trial)
                    evaluations += 1
                    if trial_fitness < fitness[i]:
                        fitness[i] = trial_fitness
                        population[i] = trial
                        success_count += 1
                if success_count > population_size * 0.2:
                    population_size = min(population_size + 1, 20 * self.dim)
                else:
                    population_size = max(population_size - 1, 5 * self.dim)

        exploration_weight = 0.5
        for _ in range(self.budget // (initial_population_size * 2)):
            adaptive_differential_evolution()
            for i in range(population_size):
                if evaluations >= self.budget:
                    return population[np.argmin(fitness)], fitness.min()
                improved = learning_guided_local_search(population[i], step_size=0.1 * exploration_weight)
                improved_fitness = func(improved)
                evaluations += 1
                if improved_fitness < fitness[i]:
                    fitness[i] = improved_fitness
                    population[i] = improved
            exploration_weight *= 0.9

        best_idx = np.argmin(fitness)
        return population[best_idx], fitness[best_idx]
